        const list = await llm.listModels(PROVIDER)
        if (Array.isArray(list) && list.length > 0) {
          const rows = []
          for (const m of list) {
            const id = m && m.id
            if (typeof id !== 'string' || id.length === 0) continue
            rows.push({ id, name: (m && typeof m.name === 'string' && m.name) ? m.name : id })
          }
